363	function escapeHtml(value: string): string {
364	  return value.replace(/[&<>'"]/g, (character) => ({
365	    "&": "&amp;",
366	    "<": "&lt;",
367	    ">": "&gt;",
368	    "'": "&#39;",
369	    '"': "&quot;",
370	  })[character] ?? character);
371	}
