373	function triggerDownload(documentRef: Document, blob: Blob, fileName: string): void {
374	  if (typeof URL.createObjectURL !== "function") return;
375	  const anchor = documentRef.createElement("a");
376	  anchor.href = URL.createObjectURL(blob);
377	  anchor.download = fileName;
378	  anchor.hidden = true;
379	  documentRef.body.append(anchor);
380	  anchor.click();
381	  anchor.remove();
382	  URL.revokeObjectURL(anchor.href);
383	}

