16	const PBKDF2_ITERATIONS = 210_000;
17	const textEncoder = new TextEncoder();
18	const textDecoder = new TextDecoder();
19	
20	function bytesToBase64(bytes: Uint8Array): string {
21	  let binary = "";
22	  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
23	  return btoa(binary);
24	}
25	
26	function base64ToBytes(value: string): Uint8Array {
27	  const binary = atob(value);
28	  const bytes = new Uint8Array(binary.length);
29	  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
30	  return bytes;
31	}
32	
33	async function deriveKey(password: string, salt: Uint8Array): Promise<CryptoKey> {
34	  if (typeof password !== "string" || password.length === 0) throw new Error("Backup password is required");
35	  const material = await crypto.subtle.importKey("raw", textEncoder.encode(password), "PBKDF2", false, ["deriveKey"]);
36	  return crypto.subtle.deriveKey({ name: "PBKDF2", salt: salt as BufferSource, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" }, material, { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
37	}
38	
39	async function blobBytes(blob: Blob): Promise<Uint8Array> {
40	  if (typeof blob.arrayBuffer === "function") return new Uint8Array(await blob.arrayBuffer());
41	  if (typeof (blob as Blob & { text?: () => Promise<string> }).text === "function") {
42	    return textEncoder.encode(await (blob as Blob & { text: () => Promise<string> }).text());
43	  }
44	  return new Uint8Array(await new Response(blob).arrayBuffer());
45	}
46	
47	async function readStores(database: IDBDatabase, kind: BackupKind): Promise<BackupPayload> {
48	  const storeNames = [...allowedBackupStores(), ...(kind === "full" ? [STORE_NAMES.originalFiles] : [])] as const;
49	  const result = await runTransaction(database, storeNames, "readonly", async (tx) => {
50	    const stores: Record<string, unknown[]> = {};
51	    for (const storeName of allowedBackupStores()) stores[storeName] = await requestToPromise<unknown[]>(tx.objectStore(storeName).getAll());
52	    let originalFiles: EncodedOriginalFile[] | undefined;
53	    if (kind === "full") {
54	      const files = await requestToPromise<StoredFile[]>(tx.objectStore(STORE_NAMES.originalFiles).getAll());
55	      originalFiles = [];
56	      for (const file of files) {
57	        const bytes = await blobBytes(file.blob);
58	        originalFiles.push({ id: file.id, createdAt: file.createdAt, updatedAt: file.updatedAt, ownerType: file.ownerType, ownerId: file.ownerId, fileName: file.fileName, fileType: file.fileType, mimeType: file.blob.type, size: bytes.byteLength, bytes: bytesToBase64(bytes) });
59	      }
60	    }
61	    return { kind, exportedAt: new Date().toISOString(), stores, ...(originalFiles ? { originalFiles } : {}) } as BackupPayload;
62	  });
63	  validateBackupPayload(result, kind);
64	  return result;
65	}
66	
67	export async function exportBackup(database: IDBDatabase, options: { kind: BackupKind; password: string }): Promise<BackupEnvelope> {
68	  const payload = await readStores(database, options.kind);
69	  const salt = crypto.getRandomValues(new Uint8Array(16));
70	  const iv = crypto.getRandomValues(new Uint8Array(12));
71	  const key = await deriveKey(options.password, salt);
72	  const ciphertext = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv: iv as BufferSource, tagLength: 128 }, key, textEncoder.encode(JSON.stringify(payload))));
73	  const saltBase64 = bytesToBase64(salt);
74	  const ivBase64 = bytesToBase64(iv);
75	  return { format: BACKUP_FORMAT, version: BACKUP_VERSION, kind: options.kind, salt: saltBase64, iv: ivBase64, kdf: { name: "PBKDF2", hash: "SHA-256", iterations: PBKDF2_ITERATIONS, salt: saltBase64 }, cipher: { name: "AES-GCM", iv: ivBase64, tagLength: 128 }, ciphertext: bytesToBase64(ciphertext) };
76	}
77	
78	export async function decryptBackup(input: unknown, password: string): Promise<BackupPayload> {
79	  validateBackupEnvelope(input);
80	  try {
81	    const key = await deriveKey(password, base64ToBytes(input.salt));
82	    const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: base64ToBytes(input.iv) as BufferSource, tagLength: 128 }, key, base64ToBytes(input.ciphertext) as BufferSource);
83	    const payload: unknown = JSON.parse(textDecoder.decode(plain));
84	    validateBackupPayload(payload, input.kind);
85	    return payload;
86	  } catch (error) {
87	    if (error instanceof Error && /Invalid backup|Unsupported backup|mismatch/.test(error.message)) throw error;
88	    throw new Error("Unable to decrypt backup");
89	  }
90	}

