111	    return;
112	  }
113	  if (!value || typeof value !== "object" || Object.getPrototypeOf(value) !== Object.prototype) {
114	    throw new Error("Invalid backup value");
115	  }
116	  for (const [key, child] of Object.entries(value)) {
117	    if (SENSITIVE_FIELD_NAMES.has(key)) throw new Error("Sensitive data is not allowed in backup stores");
118	    validateJsonValue(child);
119	  }
120	}
121	
122	export function validateBackupEnvelope(value: unknown): asserts value is BackupEnvelope {
123	  if (!value || typeof value !== "object") throw new Error("Invalid backup envelope");
124	  const envelope = value as Record<string, unknown>;
125	  hasOnlyFields(envelope, ENVELOPE_FIELDS, "backup envelope");
126	  if (envelope.format !== BACKUP_FORMAT) throw new Error("Invalid backup format");
127	  if (envelope.version !== BACKUP_VERSION) throw new Error("Unsupported backup version");
128	  if (envelope.kind !== "light" && envelope.kind !== "full") throw new Error("Invalid backup kind");
129	  if (!isCanonicalBase64(envelope.ciphertext) || !isCanonicalBase64(envelope.salt) || !isCanonicalBase64(envelope.iv)) throw new Error("Invalid backup ciphertext");
130	  const kdf = envelope.kdf as Record<string, unknown> | undefined;
131	  if (!kdf || Object.keys(kdf).length !== 4 || kdf.name !== "PBKDF2" || kdf.hash !== "SHA-256" || typeof kdf.iterations !== "number" || !Number.isInteger(kdf.iterations) || kdf.iterations < 100_000 || !isCanonicalBase64(kdf.salt)) {
132	    throw new Error("Invalid backup KDF parameters");
133	  }
134	  const cipher = envelope.cipher as Record<string, unknown> | undefined;
135	  if (!cipher || Object.keys(cipher).length !== 3 || cipher.name !== "AES-GCM" || cipher.tagLength !== 128 || !isCanonicalBase64(cipher.iv)) throw new Error("Invalid backup cipher parameters");
136	  if (kdf.salt !== envelope.salt || cipher.iv !== envelope.iv) throw new Error("Invalid backup parameter metadata");
137	  if (decodedByteLength(envelope.ciphertext) < 16 || decodedByteLength(envelope.salt) !== 16 || decodedByteLength(envelope.iv) !== 12) throw new Error("Invalid backup parameter length");
138	}
139	
140	function validateRecordArray(value: unknown, storeName: string): unknown[] {
141	  if (!Array.isArray(value)) throw new Error(`Invalid backup store: ${storeName}`);
142	  for (const record of value) {
143	    if (!record || typeof record !== "object") throw new Error(`Invalid record in store: ${storeName}`);
144	    const item = record as Record<string, unknown>;
145	    if (typeof item.id !== "string" || !item.id || !isIso(item.createdAt) || !isIso(item.updatedAt)) throw new Error(`Invalid record in store: ${storeName}`);
146	    validateJsonValue(item);
147	  }
148	  return value;
149	}
150	
151	export function validateBackupPayload(value: unknown, expectedKind?: BackupKind): asserts value is BackupPayload {
152	  if (!value || typeof value !== "object") throw new Error("Invalid backup payload");
153	  const payload = value as Record<string, unknown>;
154	  hasOnlyFields(payload, PAYLOAD_FIELDS, "backup payload");
155	  if (payload.kind !== "light" && payload.kind !== "full") throw new Error("Invalid backup payload kind");
156	  if (expectedKind && payload.kind !== expectedKind) throw new Error("Backup kind mismatch");
157	  if (!isIso(payload.exportedAt)) throw new Error("Invalid backup export timestamp");
158	  if (!payload.stores || typeof payload.stores !== "object" || Array.isArray(payload.stores)) throw new Error("Invalid backup stores");
159	  const stores = payload.stores as Record<string, unknown>;
160	  for (const key of Object.keys(stores)) {
161	    if (!ALLOWED_STORES.includes(key as (typeof ALLOWED_STORES)[number])) throw new Error(`Disallowed backup store: ${key}`);
162	    validateRecordArray(stores[key], key);
163	  }
164	  if (payload.kind === "light" && Object.prototype.hasOwnProperty.call(payload, "originalFiles")) throw new Error("Light backup cannot contain originalFiles");
165	  if (payload.kind === "full") {
166	    if (!Array.isArray(payload.originalFiles)) throw new Error("Full backup missing originalFiles");
167	    for (const file of payload.originalFiles) {
168	      if (!file || typeof file !== "object" || Object.getPrototypeOf(file) !== Object.prototype) throw new Error("Invalid original file record");
169	      const item = file as Record<string, unknown>;
170	      if (Object.keys(item).length !== 10 || typeof item.id !== "string" || !item.id || !isIso(item.createdAt) || !isIso(item.updatedAt) || (item.ownerType !== "resume" && item.ownerType !== "job-description") || typeof item.ownerId !== "string" || !item.ownerId || typeof item.fileName !== "string" || !item.fileName || (item.fileType !== "pdf" && item.fileType !== "docx") || typeof item.mimeType !== "string" || typeof item.size !== "number" || !Number.isInteger(item.size) || item.size < 0 || !isCanonicalBase64(item.bytes, item.size === 0) || decodedByteLength(item.bytes) !== item.size) throw new Error("Invalid original file record");
171	    }
172	  }
173	}

