226	function resolutionMap(session: BackupImportSession, resolutions?: BackupResolutions | null): Map<string, ImportResolution> {
227	  if (resolutions === null) throw new Error("Import conflict resolution cancelled");
228	  const result = new Map<string, ImportResolution>();
229	  for (const conflict of session.conflicts) result.set(`${conflict.storeName}:${conflict.id}`, "keep-local");
230	  const entries: BackupConflictResolution[] = Array.isArray(resolutions)
231	    ? [...resolutions]
232	    : resolutions instanceof Map
233	      ? [...resolutions.entries()].map(([key, resolution]) => {
234	        const separator = key.indexOf(":");
235	        return { storeName: key.slice(0, separator) as ImportableStoreName, id: key.slice(separator + 1), resolution };
236	      })
237	      : Object.entries(resolutions ?? {}).map(([key, resolution]) => {
238	        const separator = key.indexOf(":");
239	        return { storeName: key.slice(0, separator) as ImportableStoreName, id: key.slice(separator + 1), resolution };
240	      });
241	  for (const resolution of entries) {
242	    if (!IMPORTABLE_STORES.includes(resolution.storeName) || !["keep-local", "use-backup", "import-copy"].includes(resolution.resolution)) {
243	      throw new Error("Invalid import conflict resolution");
244	    }
245	    if (!session.conflicts.some((item) => item.storeName === resolution.storeName && item.id === resolution.id)) {
246	      throw new Error("Resolution does not match a conflict");
247	    }
248	    result.set(`${resolution.storeName}:${resolution.id}`, resolution.resolution);
249	  }
250	  return result;
251	}
