253	function remapValue(value: unknown, map: Map<string, string>, storeName?: ImportableStoreName): unknown {
254	  if (typeof value !== "string") return value;
255	  if (storeName) return map.get(`${storeName}:${value}`) ?? value;
256	  return value;
257	}
