259	function remapRecord(storeName: ImportableStoreName, source: Record<string, unknown>, ids: Map<string, string>): Record<string, unknown> {
260	  const record: Record<string, unknown> = { ...source, id: ids.get(`${storeName}:${String(source.id)}`) ?? source.id };
261	  const fieldMap: Partial<Record<string, ImportableStoreName>> = {
262	    resumeId: STORE_NAMES.resumes,
263	    currentResumeId: STORE_NAMES.resumes,
264	    originalFileId: STORE_NAMES.originalFiles,
265	    jdFileId: STORE_NAMES.originalFiles,
266	    jobDescriptionId: STORE_NAMES.jobDescriptions,
267	    applicationId: STORE_NAMES.applications,
268	    stageId: STORE_NAMES.stages,
269	    interviewId: STORE_NAMES.interviews,
270	  };
271	  for (const [field, targetStore] of Object.entries(fieldMap)) {
272	    if (field in record) record[field] = remapValue(record[field], ids, targetStore);
273	  }
274	  if (storeName === STORE_NAMES.applicationTimelineEvents) {
275	    const type = record.type;
276	    const targetStore = type === "resume-changed" ? STORE_NAMES.resumes : type === "stage-changed" ? STORE_NAMES.stages : undefined;
277	    if (targetStore) {
278	      record.fromValue = remapValue(record.fromValue, ids, targetStore);
279	      record.toValue = remapValue(record.toValue, ids, targetStore);
280	    }
281	  }
282	  if (storeName === STORE_NAMES.originalFiles) record.ownerId = remapValue(record.ownerId, ids, record.ownerType === "resume" ? STORE_NAMES.resumes : STORE_NAMES.jobDescriptions);
283	  return record;
284	}
