286	export function buildImportPlan(
287	  session: BackupImportSession,
288	  resolutions?: BackupResolutions | null,
289	  options: BuildImportPlanOptions = {},
290	): ImportPlan {
291	  const resolutionsByKey = resolutionMap(session, resolutions);
292	  const records = payloadRecords(session.payload);
293	  const ids = new Map<string, string>();
294	  for (const conflict of session.conflicts) {
295	    if (resolutionsByKey.get(`${conflict.storeName}:${conflict.id}`) === "import-copy") {
296	      const nextId = options.createId?.(conflict.storeName, conflict.id) ?? DEFAULT_ID(conflict.storeName, conflict.id);
297	      if (!nextId || nextId === conflict.id || [...ids.values()].includes(nextId)) throw new Error("Import copy ID must be a new unique ID");
298	      ids.set(`${conflict.storeName}:${conflict.id}`, nextId);
299	    }
300	  }
301	  const output: Partial<Record<ImportableStoreName, unknown[]>> = {};
302	  const operations: ImportOperation[] = [];
303	  for (const storeName of IMPORTABLE_STORES) {
304	    const rows = records.get(storeName) ?? [];
305	    const selected: unknown[] = [];
306	    for (const source of rows as Array<Record<string, unknown>>) {
307	      if (storeName !== STORE_NAMES.originalFiles) assertValidRecord(storeName, source);
308	      const key = `${storeName}:${String(source.id)}`;
309	      const resolution = resolutionsByKey.get(key);
310	      if (resolution === "keep-local") continue;
311	      const remapped = remapRecord(storeName, source, ids);
312	      if (storeName === STORE_NAMES.originalFiles) {
313	        const decoded = session.decodedOriginalFiles.find((file) => file.id === source.id);
314	        if (!decoded) throw new Error(`Missing decoded original file: ${String(source.id)}`);
315	        const file = { ...decoded, id: String(remapped.id), ownerId: String(remapped.ownerId) };
316	        assertValidRecord(storeName, file);
317	        selected.push(file);
318	        operations.push({ storeName, record: file, overwrite: resolution === "use-backup" });
319	      } else {
320	        selected.push(remapped);
321	        operations.push({ storeName, record: remapped, overwrite: resolution === "use-backup" });
322	      }
323	    }
324	    output[storeName] = selected;
325	  }
326	  return { kind: session.kind, records: output, operations };
327	}
