329	export async function commitBackupImport(database: IDBDatabase, plan: ImportPlan): Promise<void> {
330	  for (const operation of plan.operations) assertValidRecord(operation.storeName, operation.record);
331	  const stores = IMPORTABLE_STORES;
332	  await runTransaction(database, stores, "readwrite", async (transaction) => {
333	    for (const operation of plan.operations) {
334	      const store = transaction.objectStore(operation.storeName);
335	      await requestToPromise(operation.overwrite ? store.put(operation.record) : store.add(operation.record));
336	    }
337	  });
338	}

