 15	export function requestToPromise<T>(request: IDBRequest<T>): Promise<T> {
 16	  return new Promise((resolve, reject) => {
 17	    request.addEventListener("success", () => resolve(request.result));
 18	    request.addEventListener("error", () =>
 19	      reject(request.error ?? new Error("IndexedDB request failed")),
 20	    );
 21	  });
 22	}
