 24	export function transactionToPromise(transaction: IDBTransaction): Promise<void> {
 25	  return new Promise((resolve, reject) => {
 26	    transaction.addEventListener("complete", () => resolve());
 27	    transaction.addEventListener("abort", () =>
 28	      reject(transaction.error ?? new Error("IndexedDB transaction aborted")),
 29	    );
 30	    transaction.addEventListener("error", () =>
 31	      reject(transaction.error ?? new Error("IndexedDB transaction failed")),
 32	    );
 33	  });
 34	}
