 36	export async function runTransaction<T>(
 37	  database: IDBDatabase,
 38	  storeNames: StoreName | readonly StoreName[],
 39	  mode: IDBTransactionMode,
 40	  operation: (transaction: IDBTransaction) => T | Promise<T>,
 41	): Promise<T> {
 42	  const transaction = database.transaction(storeNames, mode);
 43	  const completion = transactionToPromise(transaction);
 44	
 45	  try {
 46	    const result = await operation(transaction);
 47	    await completion;
 48	    return result;
 49	  } catch (error) {
 50	    try {
 51	      transaction.abort();
 52	    } catch {
 53	      // The transaction may already have completed or aborted.
 54	    }
 55	    await completion.catch(() => undefined);
 56	    throw error;
 57	  }
 58	}
