 60	export function openCareerDatabase(
 61	  options: OpenDatabaseOptions = {},
 62	): Promise<IDBDatabase> {
 63	  const factory = options.factory ?? indexedDB;
 64	  const name = options.name ?? DATABASE_NAME;
 65	  const version = options.version ?? DATABASE_VERSION;
 66	
 67	  return new Promise((resolve, reject) => {
 68	    const request = factory.open(name, version);
 69	    let upgradeError: unknown;
 70	
 71	    request.addEventListener("upgradeneeded", (event) => {
 72	      try {
 73	        const transaction = request.transaction;
 74	        if (!transaction) {
 75	          throw new Error("IndexedDB upgrade transaction is unavailable");
 76	        }
 77	        ensureSchema(request.result, transaction);
 78	        runMigrations(transaction, event.oldVersion, (error) => {
 79	          if (upgradeError === undefined) {
 80	            upgradeError = error;
 81	          }
 82	        });
 83	      } catch (error) {
 84	        upgradeError = error;
 85	        request.transaction?.abort();
 86	      }
 87	    });
 88	    request.addEventListener("success", () => resolve(request.result));
 89	    request.addEventListener("error", () =>
 90	      reject(
 91	        upgradeError ?? request.error ?? new Error("Unable to open IndexedDB"),
 92	      ),
 93	    );
 94	    request.addEventListener("blocked", () =>
 95	      reject(new Error(`IndexedDB upgrade is blocked for ${name}`)),
 96	    );
 97	  });
 98	}
