110	class IndexedDbRepository<T extends BaseRecord> implements Repository<T> {
111	  readonly #database: IDBDatabase;
112	  readonly #storeName: StoreName;
113	  readonly #now: () => string;
114	  readonly #createId: () => string;
115	  readonly #validate?: Validator<T>;
116	
117	  constructor(
118	    database: IDBDatabase,
119	    storeName: StoreName,
120	    dependencies: Required<RepositoryDependencies>,
121	    validate?: Validator<T>,
122	  ) {
123	    this.#database = database;
124	    this.#storeName = storeName;
125	    this.#now = dependencies.now;
126	    this.#createId = dependencies.createId;
127	    this.#validate = validate;
128	  }
129	
130	  async create(input: CreateInput<T>): Promise<T> {
131	    const timestamp = this.#now();
132	    assertAbsoluteIsoTimestamp(timestamp, "createdAt");
133	    const record = {
134	      ...input,
135	      id: this.#createId(),
136	      createdAt: timestamp,
137	      updatedAt: timestamp,
138	    } as T;
139	    validateBase(record);
140	    this.#validate?.(record);
141	
142	    await runTransaction(this.#database, this.#storeName, "readwrite", (transaction) =>
143	      requestToPromise(transaction.objectStore(this.#storeName).add(record)),
144	    );
145	    return record;
146	  }
147	
148	  get(id: string): Promise<T | undefined> {
149	    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
150	      requestToPromise<T | undefined>(
151	        transaction.objectStore(this.#storeName).get(id),
152	      ),
153	    );
154	  }
155	
156	  list(): Promise<T[]> {
157	    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
158	      requestToPromise<T[]>(transaction.objectStore(this.#storeName).getAll()),
159	    );
160	  }
161	
162	  async update(id: string, patch: UpdateInput<T>): Promise<T> {
163	    return runTransaction(this.#database, this.#storeName, "readwrite", async (transaction) => {
164	      const store = transaction.objectStore(this.#storeName);
165	      const existing = await requestToPromise<T | undefined>(store.get(id));
166	      if (!existing) {
167	        throw new Error(`Record not found: ${id}`);
168	      }
169	
170	      const updated = {
171	        ...existing,
172	        ...patch,
173	        id: existing.id,
174	        createdAt: existing.createdAt,
175	        updatedAt: nextTimestamp(this.#now(), existing.updatedAt),
176	      };
177	      validateBase(updated);
178	      this.#validate?.(updated);
179	      await requestToPromise(store.put(updated));
180	      return updated;
181	    });
182	  }
183	
184	  async delete(id: string): Promise<void> {
185	    await runTransaction(this.#database, this.#storeName, "readwrite", (transaction) =>
186	      requestToPromise(transaction.objectStore(this.#storeName).delete(id)),
187	    );
188	  }
189	
190	  findByIndex(
191	    indexName: string,
192	    query: IDBValidKey | IDBKeyRange,
193	  ): Promise<T[]> {
194	    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
195	      requestToPromise<T[]>(
196	        transaction.objectStore(this.#storeName).index(indexName).getAll(query),
197	      ),
198	    );
199	  }
200	}
