 60	function importErrorMessage(error: unknown): string {
 61	  const message = error instanceof Error ? error.message : "";
 62	  if (error instanceof SyntaxError) {
 63	    return "备份文件损坏或不是有效 JSON，未导入任何数据；请重新选择文件。";
 64	  }
 65	  if (/Unable to decrypt/i.test(message)) {
 66	    return "密码错误或备份文件已损坏，未导入任何数据；请检查密码或重新选择文件。";
 67	  }
 68	  if (/Invalid backup|Unsupported backup|mismatch|Invalid record|Duplicate record|Disallowed backup/i.test(message)) {
 69	    return `备份格式校验失败，未导入任何数据；请重新选择有效备份。${message ? `（${message}）` : ""}`;
 70	  }
 71	  return "备份无法读取，未导入任何数据；请检查文件后重试。";
 72	}
