 36	function readFileText(file: File): Promise<string> {
 37	  if (typeof file.text === "function") return file.text();
 38	  return new Promise((resolve, reject) => {
 39	    const reader = new FileReader();
 40	    reader.addEventListener("load", () => resolve(String(reader.result ?? "")));
 41	    reader.addEventListener("error", () => reject(reader.error ?? new Error("Unable to read backup file")));
 42	    reader.readAsText(file);
 43	  });
 44	}
