 46	function triggerBackupDownload(documentRef: Document, envelope: BackupEnvelope): void {
 47	  if (typeof URL.createObjectURL !== "function") return;
 48	  const blob = new Blob([JSON.stringify(envelope)], { type: "application/json" });
 49	  const href = URL.createObjectURL(blob);
 50	  const anchor = documentRef.createElement("a");
 51	  anchor.href = href;
 52	  anchor.download = `career-backup-${envelope.kind}-${new Date().toISOString().slice(0, 10)}.json`;
 53	  anchor.hidden = true;
 54	  documentRef.body.append(anchor);
 55	  anchor.click();
 56	  anchor.remove();
 57	  URL.revokeObjectURL(href);
 58	}
