291	      root.querySelector<HTMLButtonElement>('[data-action="review-conflicts"]')!.click();
292	      root.querySelector<HTMLButtonElement>('[data-action="preview-import"]')!.click();
293	      root.querySelector<HTMLButtonElement>('[data-action="confirm-import"]')!.click();
294	      await waitFor(() => root.querySelector(".backup-panel__status")?.textContent?.includes("导入完成") === true);
295	
296	      target.close();
297	      target = undefined;
298	      reopened = await openCareerDatabase({ name: targetName });
299	      const readTransaction = reopened.transaction(STORE_NAMES.stages, "readonly");
300	      const stages = await requestToPromise<Array<{ id: string }>>(readTransaction.objectStore(STORE_NAMES.stages).getAll());
301	      await transactionToPromise(readTransaction);
302	      expect(stages).toContainEqual(expect.objectContaining({ id: "stage-from-backup" }));
303	      expect(fetchSpy).not.toHaveBeenCalled();
304	    } finally {
305	      source?.close();
306	      target?.close();
307	      reopened?.close();
308	      await deleteCareerDatabase(sourceName);
309	      await deleteCareerDatabase(targetName);
310	    }
311	  });
312	});

